import { sendEmail } from "../notifications/channel-notifiers.mjs";
import { notificationRepository } from "../repositories/notification-repository.mjs";
export function sendDigest(user, items) { const deliveries=[]; for(let i=0;i<items.length;i+=2){const message=`Digest: ${items.slice(i,i+2).join(", ")}`;notificationRepository.save(makeNotification(user.id,message));deliveries.push(sendEmail(user,message));}return deliveries;}

